const t = $('Telegram Trigger').first().json;
const id = t.message && t.message.chat ? t.message.chat.id : '';
const text = (t.message && t.message.text ? t.message.text : '').toString().trim();
const s = $input.first() ? $input.first().json : {};
const estado = (s && s.pantalla_actual) ? s.pantalla_actual : 'inicio';
const carrito = (s && s['carrito-temporal']) ? s['carrito-temporal'] : '[]';
return [{ json: { id_usuario: id, text: text, pantalla_actual: estado, carrito: carrito } }];

const p = $input.first() ? $input.first().json : {};
const text = (p.text || '').toString().trim().toLowerCase();
const comandos = ['estado', '/estado', 'mi pedido', 'mis pedidos', 'seguimiento', 'status'];
const esEstado = comandos.indexOf(text) !== -1;
return [{ json: { id_usuario: p.id_usuario, text: p.text, pantalla_actual: p.pantalla_actual, carrito: p.carrito, esEstado: esEstado } }];

const rows = $input.all().filter(i => i.json && i.json.id_pedido);
if (rows.length === 0) {
  return [{ json: { mensaje: '📦 Aún no tienes pedidos registrados. Escribe cualquier cosa para ver el menú y hacer tu primer pedido.' } }];
}
rows.sort((a, b) => String(b.json.id_pedido).localeCompare(String(a.json.id_pedido)));
const p = rows[0].json;
let msg = '📦 Estado de tu último pedido\n\n';
msg += 'Pedido: ' + p.id_pedido + '\n';
msg += 'Estado: ' + p.estado + '\n';
msg += 'Total: $' + p.total_pago + '\n';
msg += 'Fecha: ' + p.fecha + ' ' + (p.hora || '');
return [{ json: { mensaje: msg } }];

const opcion = ($('Preparar Sesión').first().json.text || '').trim();
let categoria = '';
if (opcion === '1') categoria = 'Bebidas';
if (opcion === '2') categoria = 'Comidas';
if (opcion === '3') categoria = 'Snacks';
if (!categoria) {
  return [{ json: { valido: false, mensaje: '❌ Opción no válida. Escribe 1, 2 o 3.' } }];
}
const productos = $input.all().filter(i => String(i.json.categoria || '').toLowerCase() === categoria.toLowerCase());
if (productos.length === 0) {
  return [{ json: { valido: false, mensaje: 'No hay productos en ' + categoria + '.' } }];
}
let msg = '🍽️ ' + categoria + '\n\n';
for (const p of productos) {
  msg += p.json.id_productos + ' | ' + p.json.nombre + ' - $' + p.json.precio + ' (stock: ' + p.json.stock + ')\n';
  msg += '📝 ' + p.json.descripcion + '\n\n';
}
msg += 'Para pedir escribe: id_producto cantidad  (ej: 1 2)';
return [{ json: { valido: true, categoria: categoria, mensaje: msg } }];

const prep = $('Preparar Sesión').first().json;
const text = (prep.text || '').trim();
const parts = text.split(' ').filter(p => p !== '');
const idProd = parts[0];
const cantidad = parseInt(parts[1], 10);
const id_usuario = prep.id_usuario;
let carrito = [];
try { carrito = JSON.parse(prep.carrito || '[]'); } catch (e) { carrito = []; }
if (!idProd || isNaN(cantidad) || cantidad <= 0) {
  return [{ json: { ok: false, id_usuario: id_usuario, mensaje: '❌ Formato inválido. Escribe: id_producto cantidad (ej: 1 2)' } }];
}
const prod = $input.all().find(i => String(i.json.id_productos) === String(idProd));
if (!prod) {
  return [{ json: { ok: false, id_usuario: id_usuario, mensaje: '❌ Producto no encontrado. Revisa el id.' } }];
}
const stock = parseInt(prod.json.stock, 10) || 0;
const existente = carrito.find(c => String(c.id_productos) === String(idProd));
const yaEnCarrito = existente ? existente.cantidad : 0;
if (cantidad + yaEnCarrito > stock) {
  return [{ json: { ok: false, id_usuario: id_usuario, mensaje: '⚠️ Stock insuficiente para ' + prod.json.nombre + '. Disponible: ' + stock + ', en carrito: ' + yaEnCarrito + '.' } }];
}
const precio = parseFloat(prod.json.precio) || 0;
if (existente) { existente.cantidad += cantidad; }
else { carrito.push({ id_productos: String(idProd), nombre: prod.json.nombre, precio: precio, cantidad: cantidad }); }
let total = 0;
for (const c of carrito) { total += (parseFloat(c.precio) || 0) * c.cantidad; }
const mensaje = '✅ Agregado: ' + cantidad + ' x ' + prod.json.nombre + '\nTotal actual: $' + total.toFixed(2) + '\n\n1) Seguir comprando\n2) Ver carrito y confirmar';
return [{ json: { ok: true, id_usuario: id_usuario, carrito: JSON.stringify(carrito), total: total.toFixed(2), mensaje: mensaje } }];

const text = ($('Preparar Sesión').first().json.text || '').trim();
let accion = 'invalid';
if (text === '1') accion = 'seguir';
else if (text === '2') accion = 'ver';
return [{ json: { accion: accion } }];

let msg = '📋 ¡Bienvenido a DeliveryBot!\n\nElige una categoría (escribe el número):\n\n';
const rows = $input.all().slice(0, 3);
for (const item of rows) {
  msg += item.json.n_categorias + '. ' + item.json.clase + '\n';
}
return [{ json: { mensaje: msg } }];

const prep = $('Preparar Sesión').first().json;
let carrito = [];
try { carrito = JSON.parse(prep.carrito || '[]'); } catch (e) { carrito = []; }
let msg = '🛒 Tu carrito:\n\n';
let total = 0;
for (const c of carrito) {
  const sub = (parseFloat(c.precio) || 0) * c.cantidad;
  total += sub;
  msg += c.cantidad + ' x ' + c.nombre + ' - $' + sub.toFixed(2) + '\n';
}
msg += '\n💰 Total: $' + total.toFixed(2) + '\n\n¿Confirmar pedido? (si / no)';
return [{ json: { mensaje: msg, total: total.toFixed(2) } }];

const text = ($('Preparar Sesión').first().json.text || '').trim().toLowerCase();
let decision = 'invalid';
if (['si','sí','s','1','confirmar'].indexOf(text) !== -1) decision = 'si';
else if (['no','n','2','cancelar'].indexOf(text) !== -1) decision = 'no';
return [{ json: { decision: decision } }];

const prep = $('Preparar Sesión').first().json;
let carrito = [];
try { carrito = JSON.parse(prep.carrito || '[]'); } catch (e) { carrito = []; }
const id_pedido = 'PED-' + Date.now();
let total = 0;
const detalles = [];
for (const c of carrito) {
  const sub = (parseFloat(c.precio) || 0) * c.cantidad;
  total += sub;
  detalles.push(c.cantidad + 'x ' + c.nombre);
}
const now = new Date();
const fecha = now.toISOString().slice(0, 10);
const hora = now.toISOString().slice(11, 19);
return [{ json: {
  id_pedido: id_pedido,
  id_usuario: prep.id_usuario,
  detalles_pedido: JSON.stringify(carrito),
  detalles_texto: detalles.join(', '),
  total_pago: total.toFixed(2),
  estado: 'Recibido',
  fecha: fecha,
  hora: hora,
  carrito: prep.carrito
} }];

